import numpy as np, os, glob, nibabel as nib
from skimage.transform import resize
from skimage.feature import match_template
S='/private/tmp/claude-501/-Users-hoomham-Hooman-Work-Codes-2026-ASAP-Recon/c77ac6c0-b767-4758-aada-ee5eb125dd2f/scratchpad/'
g=np.load(S+'query_gray.npy'); tiles=[g[40:198,a:b] for a,b in [(30,261),(340,570),(648,879)]]
facs=[2.4,2.8,3.3,3.8,4.4,5.0]
Qs={f:[resize(t,(int(round(t.shape[0]/f)),int(round(t.shape[1]/f))),anti_aliasing=True) for t in tiles] for f in facs}
X='/Volumes/HoomHamExt/Work/Codes/2026_PCA_registration/xecs_registrations_2026-09-15'
A='/Volumes/HoomHamExt/Work/Analysis'
srcs=[(os.path.basename(os.path.dirname(d)),d) for d in sorted(glob.glob(X+'/*/stack.npy'))]
in104={s for s,_ in srcs}
for d in sorted(glob.glob(A+'/*/reg/5000/registered.nii')):
    sess=d.split('/')[-4]
    if sess not in in104: srcs.append(('LEGACY_'+sess,d))
print(len(srcs),'sources',flush=True)
def load(d):
    if d.endswith('.npy'): return np.load(d)
    return np.moveaxis(np.asarray(nib.load(d).dataobj),-1,0)
res=[]
for sess,d in srcs:
    try: st=np.abs(load(d)).astype(np.float32)
    except Exception as e: print('skip',sess,e,flush=True); continue
    p=np.percentile(st,99.5); ei=int(np.argmax([(b>0.25*p).sum() for b in st])); v=st[ei]/p
    m=st.mean(0)>0.15*st.mean(0).max(); ys=np.where(m.any(axis=(0,2)))[0]
    if len(ys)==0: continue
    best=(-1,None)
    for flip in (False,True):
        for f in facs:
            sc=np.full((3,len(ys)),-1.0)
            for j,y in enumerate(ys):
                sl=v[:,y,:]; sl=sl[:,::-1] if flip else sl
                for q in range(3):
                    sc[q,j]=match_template(sl,Qs[f][q],pad_input=True).max()
            score=sc.max(1).mean()
            if score>best[0]: best=(score,(flip,f,ys[sc.argmax(1)].tolist()))
    res.append((best[0],sess,best[1])); print(f'{sess} {best[0]:.3f} {best[1]}',flush=True)
res.sort(reverse=True); print('\nTOP 12:')
for r in res[:12]: print(f'  {r[0]:.3f}  {r[1]}  flip,f,y={r[2]}')
np.save(S+'match2.npy',np.array(res,dtype=object))
EOF
